var t=[{title:`Definities`,text:`Een antagonistische superset wisselt tegenovergestelde bewegingspatronen af, zoals een pers gevolgd door een row. Een compound set koppelt twee oefeningen voor dezelfde spiergroep. Een circuit kan vijf stations doorlopen voordat je rust en herhaalt. EMOM betekent “every minute on the minute” (elke minuut op de minuut), en AMRAP betekent “as many rounds or repetitions as possible” (zoveel ronden of herhalingen mogelijk) in een vaste tijd.`},{title:`Waarom je ze gebruikt`,text:`Een duwoefening koppelen aan een trekoefening laat de ene spiergroep werken terwijl een andere rust, wat tijd kan besparen. Circuits kunnen weerstands- en cardiowerk combineren in een kleine ruimte. Veel mensen denken dat ze meer kracht of spiermassa opbouwen, maar dat doen ze niet automatisch; de kwaliteit van het totale werk en je herstel bepalen dat nog steeds.`},{title:`Vermoeidheid beheersen`,text:`Een zware squat gekoppeld aan een zware deadlift kan beide lifts slechter maken, vooral voor beginners. Koppel oefeningen die niet te veel met elkaar concurreren en rust lang genoeg om de controle te houden. Technische lifts en explosieve sprongen hebben vaak meer herstel nodig dan een circuit op tijd geeft. Gebruik supersets als je weinig tijd hebt en de combinatie bij je doel past. Kort rust niet in om een tijddoel te halen, en sla circuits vol sprongen of lastige bewegingen over als je ruimte, geluidslimieten of lichaam die uitsluiten.`},{title:`Voorbeeld`,text:`Doe tien beheerste incline push-ups, dan tien ondersteunde rows en rust dan 90 seconden; herhaal drie keer. Een conditiecircuit kan step-ups, een lichte carry en marcheren gebruiken, met geplande rust. Kies een aantal rondes dat je kunt volhouden zonder te haasten ten koste van je techniek.`}];var i=[{label:`NSCA: tijdefficiënt trainen`,url:`https://www.nsca.com/education/articles/ptq/time-efficient-training`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};